mapper.sql:
WHERE i.tenant_id = #{tenantId} AND i.deleted = 0

    AND i.project_id = #{projectId}
    AND i.project_id IS NULL
    AND (i.project_id IS NULL OR i.project_id IN #{id})

AND i.business_key LIKE #{businessKey}
AND (d.name LIKE #{definitionKeyword} OR d.code LIKE #{definitionKeyword})
AND i.status = #{status}
AND (u.display_name LIKE #{starterKeyword} OR u.username LIKE #{starterKeyword})
AND DATE(i.created_at) >= #{createdFrom}
AND DATE(i.created_at) <= #{createdTo}
